------------ import ------------
local KTool = CS.Engine.Lib.KTool
local Button = CS.UnityEngine.UI.Button
------------ import ------------

------------ define ------------
local ANIMA_DEFAULT = "Default"
local ANIMA_SELECTED = "Selected"
local ANIMA_CANCEL = "Cancel"
local ANIMA_CONFIRM = "Confirm"
local ANIMA_EXIT = "Exit"
------------ define ------------

---@class TrainFieldElementNode
---@field SelectedMask                      UnityEngine.RectTransform
---@field AnimRoot                          UnityEngine.Animator
local TrainFieldElementNode = Class('TrainFieldElementNode')

------------ LifeCycle ------------

function TrainFieldElementNode:__init()
    self:CleanField()
end

function TrainFieldElementNode:__delete()
    self:CleanField()
end

function TrainFieldElementNode:Awake()
    self.elementType = 0
    self.btn = KTool.GetComponent(self.controller.gameObject, typeof(Button))
end

function TrainFieldElementNode:Start()
end

function TrainFieldElementNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

------------ LifeCycle ------------

function TrainFieldElementNode:CleanField()
    self.btn = nil
    self.elementType = nil
    self.cbClick = nil
    self.boolSaved = nil
end

function TrainFieldElementNode:PlayAnimation(name)
    if not IsNull(self.AnimRoot) then
        self.AnimRoot:Play(name)
    end
end

function TrainFieldElementNode:AnimationDEFAULT()
    self:PlayAnimation(ANIMA_DEFAULT)
end

function TrainFieldElementNode:AnimationSELECTED()
    self:PlayAnimation(ANIMA_SELECTED)
end

function TrainFieldElementNode:AnimationCANCEL()
    self:PlayAnimation(ANIMA_CANCEL)
end

function TrainFieldElementNode:SetSelectedRootStatus(bool)
    bool = checkBool(bool)
    if not IsNull(self.SelectedMask) then
        KTool.SetActive(self.SelectedMask.gameObject, bool)
    end
    if bool then
        self:AnimationSELECTED()
    end
    if (not bool) and self.boolSaved then
        self:AnimationCANCEL()
    end
    self.boolSaved = bool
end

function TrainFieldElementNode:PlayAnimationOnClose()
    self:PlayAnimation(checkBool(self.boolSaved) and ANIMA_CONFIRM or ANIMA_EXIT)
end

function TrainFieldElementNode:SetElementType(type)
    self.elementType = checkNumber(type)
end

function TrainFieldElementNode:SetCBClick(cb)
    if not IsNull(self.btn) then
        SetButtonAction(self.btn, function()
            cb(checkNumber(self.elementType))
        end)
    end
end

return TrainFieldElementNode